use Time;
use Random;
use IO;
use Math;

config const numLocalesConfig = Locales.size;

record Tensor {
  var s0: int;
  var s1: int;
  var dom: domain(1);
  var  [dom] real;

  proc init(shape0: int, shape1: int) {
    this.s0 = shape0;
    this.s1 = shape1;
    const size = shape0 * shape1;
    this.dom = {0..<size};
    init this;
    forall i in this.dom do this.data[i] = 0.0;
  }

  proc shape(idx: int): int {
    if idx == 0 then return s0;
    else if idx == 1 then return s1;
    else {
      writeln("Invalid shape index");
      return -1;
    }
  }

  proc numElements(): int {
    return s0 * s1;
  }

  proc ref fill(value: real) {
    forall i in dom do data[i] = value;
  }

  proc ref fillRandom(seed: int) {
    var rng = new randomStream(real, seed);
    const scale = sqrt(2.0 / (s0 + s1):real);
    forall i in dom do data[i] = (rng.next() * 2.0 - 1.0) * scale;
  }

  proc ref add(other: Tensor) {
    if s0 != other.s0 || s1 != other.s1 then {
      writeln("Shape mismatch in add");
      return;
    }
    forall i in dom do data[i] += other.data[i];
  }

  proc ref matmul(B: Tensor): Tensor {
    if this.s1 != B.s0 then {
      writeln("Matmul shape mismatch");
      var emptyTensor = new Tensor(0, 0);
      return emptyTensor;
    }
    var C = new Tensor(this.s0, B.s1);
    C.fill(0.0);
    forall i in 0..<this.s0 {
      for j in 0..<B.s1 {
        var sum = 0.0;
        for k in 0..<this.s1 {
          const idxA = i * this.s1 + k;
          const idxB = k * B.s1 + j;
          if idxA < this.dom.size && idxB < B.dom.size then {
            sum += this.data[idxA] * B.data[idxB];
          }
        }
        const idxC = i * C.s1 + j;
        if idxC < C.dom.size then C.data[idxC] = sum;
      }
    }
    return C;
  }

  proc norm2(): real {
    var norm = 0.0;
    for v in data do norm += v * v;
    return sqrt(norm);
  }

  proc ref divScalar(val: real) {
    if abs(val) < 1.0e-10 then {
      writeln("Division by zero or near-zero value");
      return;
    }
    forall i in dom do data[i] /= val;
  }

  proc ref relu() {
    forall i in dom do if data[i] < 0.0 then data[i] = 0.0;
  }

  proc ref gelu() {
    const sqrt2overPi = sqrt(2.0 / pi);
    const coeff = 0.044715;
    forall i in dom {
      const x = data[i];
      const xCubed = x * x * x;
      const inner = sqrt2overPi * (x + coeff * xCubed);
      data[i] = 0.5 * x * (1.0 + tanh(inner));
    }
  }

  proc ref layerNorm() {
    var mean = 0.0;
    for v in data do mean += v;
    mean /= dom.size:real;
    var variance = 0.0;
    for v in data do variance += (v - mean) * (v - mean);
    variance /= dom.size:real;
    const std = sqrt(variance + 1.0e-5);
    forall i in dom do data[i] = (data[i] - mean) / std;
  }
}

class QuantumSimulator {
  const numQubits: int = 20;
  const shots: int = 128800;
  var stateDom: domain(1);
  var state: [stateDom] complex(64);
  var rng: randomStream(real);

  proc init() {
    const size = 1 << numQubits;
    this.stateDom = {0..<size};
    init this;
    forall i in this.stateDom do this.state[i] = 0.0 + 0.0i;
    this.state[0] = 1.0 + 0.0i;
    this.rng = new randomStream(real, 12345);
  }

  proc ref applyHadamard(q: int) {
    if q < 0 || q >= numQubits then {
      writeln("Invalid qubit index for Hadamard");
      return;
    }
    const stride = 1 << q;
    const half = stateDom.size / 2;
    const sqrtHalf = 1.0 / sqrt(2.0);
    forall i in 0..<half {
      const base = (i / stride) * (2 * stride) + (i % stride);
      const idx0 = base;
      const idx1 = base + stride;
      if idx0 < stateDom.size && idx1 < stateDom.size then {
        const amp0 = state[idx0];
        const amp1 = state[idx1];
        state[idx0] = (amp0 + amp1) * sqrtHalf;
        state[idx1] = (amp0 - amp1) * sqrtHalf;
      }
    }
  }

  proc ref applyRotation(q: int, angle: real) {
    if q < 0 || q >= numQubits then {
      writeln("Invalid qubit index for Rotation");
      return;
    }
    const stride = 1 << q;
    const half = stateDom.size / 2;
    const cosA = cos(angle / 2.0);
    const sinA = sin(angle / 2.0);
    forall i in 0..<half {
      const base = (i / stride) * (2 * stride) + (i % stride);
      const idx0 = base;
      const idx1 = base + stride;
      if idx0 < stateDom.size && idx1 < stateDom.size then {
        const amp0 = state[idx0];
        const amp1 = state[idx1];
        state[idx0] = cosA * amp0 - sinA * amp1;
        state[idx1] = sinA * amp0 + cosA * amp1;
      }
    }
  }

  proc measure(): int {
    var probsDom = {0..<stateDom.size};
    var probs: [probsDom] real;
    var totalProb = 0.0;
    for i in probsDom {
      const re = state[i].re;
      const im = state[i].im;
      probs[i] = re * re + im * im;
      totalProb += probs[i];
    }
    for i in probsDom do probs[i] /= totalProb;
    const r = rng.next();
    var cum = 0.0;
    for i in probsDom {
      cum += probs[i];
      if r <= cum then return i;
    }
    return stateDom.size - 1;
  }

  proc ref simulateShots(): [0..<shots] int {
    var outcomes: [0..<shots] int;
    for i in 0..<shots {
      this.applyHadamard(0);
      this.applyRotation(1, 0.5);
      outcomes[i] = this.measure();
      forall j in this.stateDom do this.state[j] = 0.0 + 0.0i;
      this.state[0] = 1.0 + 0.0i;
    }
    return outcomes;
  }
}

class FMRNLayer {
  var dimVal: int;
  var dState: int;
  var grid: int;
  var nodeFeat: int;
  var timeDim: int;
  var kanCoeffsDom: domain(2);
  var kanCoeffs: [kanCoeffsDom] real;
  var kanBiasesDom: domain(1);
  var kanBiases: [kanBiasesDom] real;
  var ssmADom: domain(1);
  var ssmA: [ssmADom] real;
  var ssmBDom: domain(1);
  var ssmB: [ssmBDom] real;
  var ssmCDom: domain(1);
  var ssmC: [ssmCDom] real;
  var ssmDDom: domain(1);
  var ssmD: [ssmDDom] real;
  var tgnWeightsDom: domain(2);
  var tgnWeights: [tgnWeightsDom] real;
  var tgnBiasesDom: domain(1);
  var tgnBiases: [tgnBiasesDom] real;
  var layerIdx: int;
  var rng: randomStream(real);

  proc init(dimVal: int, dState: int, grid: int, nodeFeat: int, timeDim: int, idx: int) {
    this.dimVal = dimVal;
    this.dState = dState;
    this.grid = grid;
    this.nodeFeat = nodeFeat;
    this.timeDim = timeDim;
    this.kanCoeffsDom = {0..<grid, 0..<dimVal};
    this.kanBiasesDom = {0..<dimVal};
    this.ssmADom = {0..<dState};
    this.ssmBDom = {0..<dState};
    this.ssmCDom = {0..<dState};
    this.ssmDDom = {0..<dState};
    this.tgnWeightsDom = {0..<nodeFeat, 0..<timeDim};
    this.tgnBiasesDom = {0..<nodeFeat};
    this.layerIdx = idx;
    init this;
    this.rng = new randomStream(real, idx + 1);
    const kanScale = sqrt(2.0 / (grid + dimVal):real);
    forall (i, j) in kanCoeffsDom do kanCoeffs[i, j] = (rng.next() * 2.0 - 1.0) * kanScale;
    forall i in kanBiasesDom do kanBiases[i] = 0.0;
    const ssmScale = 0.1;
    forall i in ssmADom do ssmA[i] = (rng.next() * 2.0 - 1.0) * ssmScale - 0.5;
    forall i in ssmBDom do ssmB[i] = (rng.next() * 2.0 - 1.0) * ssmScale;
    forall i in ssmCDom do ssmC[i] = (rng.next() * 2.0 - 1.0) * ssmScale;
    forall i in ssmDDom do ssmD[i] = 0.0;
    const tgnScale = sqrt(2.0 / (nodeFeat + timeDim):real);
    forall (i, j) in tgnWeightsDom do tgnWeights[i, j] = (rng.next() * 2.0 - 1.0) * tgnScale;
    forall i in tgnBiasesDom do tgnBiases[i] = 0.0;
  }
}

record FMRNConfig {
  var dim: int = 18432;
  var layers: int = 768;
  var seqLen: int = 128000;
  var batchSize: int = 1024;
  var epochs: int = 400;
  var lr: real = 0.0001;
  var sparsity: real = 0.05;
  var ssmDState: int = 16;
  var kanGrid: int = 5;
  var tgnNodeFeat: int = 64;
  var tgnTimeDim: int = 64;
  var vocabSize: int = 50257;
  var quantumQubits: int = 20;
}

class CelestialZO {
  var lr: real;
  var momentum: real;
  var velocityDom: domain(1);
  var velocity: [velocityDom] real;

  proc init(learningRate: real) {
    this.lr = learningRate;
    this.momentum = 0.9;
    this.velocityDom = {0..<1};
    init this;
    forall i in velocityDom do velocity[i] = 0.0;
  }

  proc ref step(ref params: Tensor, gradients: Tensor) {
    if params.dom.size != gradients.dom.size then {
      writeln("Parameter and gradient size mismatch");
      return;
    }
    if velocityDom.size != params.dom.size {
      this.velocityDom = {0..<params.dom.size};
      forall i in velocityDom do velocity[i] = 0.0;
    }
    forall i in params.dom {
      velocity[i] = momentum * velocity[i] - lr * gradients.data[i];
      params.data[i] += velocity[i];
    }
  }
}

class FMRNModel {
  var config: FMRNConfig;
  var layersDom: domain(1);
  var layers: [layersDom] owned FMRNLayer;
  var weights: Tensor;
  var embeddings: Tensor;
  var ssmStatesDom: domain(1);
  var ssmStates: [ssmStatesDom] Tensor;
  var tgnMemoryDom: domain(1);
  var tgnMemory: [tgnMemoryDom] Tensor;
  var quantum: owned QuantumSimulator;
  var optimizer: owned CelestialZO;

  proc init(conf: FMRNConfig) {
    this.config = conf;
    this.layersDom = {0..<conf.layers};
    this.ssmStatesDom = {0..<conf.layers};
    this.tgnMemoryDom = {0..<conf.ssmDState};
    this.weights = new Tensor(conf.dim, conf.vocabSize);
    this.embeddings = new Tensor(conf.vocabSize, conf.dim);
    init this;
    this.embeddings.fillRandom(42);
    this.weights.fillRandom(43);
    for i in layersDom {
      layers[i] = new owned FMRNLayer(config.dim, config.ssmDState, config.kanGrid, config.tgnNodeFeat, config.tgnTimeDim, i);
    }
    for i in ssmStatesDom {
      ssmStates[i] = new Tensor(config.batchSize, config.ssmDState);
      ssmStates[i].fill(0.0);
    }
    for i in tgnMemoryDom {
      tgnMemory[i] = new Tensor(config.batchSize, config.tgnNodeFeat);
      tgnMemory[i].fill(0.0);
    }
    if config.quantumQubits > 0 then quantum = new owned QuantumSimulator();
    optimizer = new owned CelestialZO(config.lr);
  }

  proc forward(inputDom: domain(1), input: [inputDom] real): Tensor {
    var embeds = embed(inputDom, input);
    embeds.layerNorm();
    for l in 0..<config.layers {
      var residual = new Tensor(embeds.s0, embeds.s1);
      forall i in residual.dom do residual.data[i] = embeds.data[i];
      var kanOut = kanLayer(embeds, l);
      kanOut.gelu();
      kanOut.layerNorm();
      var ssmOut = ssmStep(kanOut, l);
      ssmOut.gelu();
      ssmOut.layerNorm();
      var tgnOut = tgnUpdate(ssmOut, l);
      tgnOut.gelu();
      tgnOut.add(residual);
      tgnOut.layerNorm();
      embeds = tgnOut;
    }
    var logits = embeds.matmul(weights);
    return logits;
  }

  proc embed(inputDom: domain(1), input: [inputDom] real): Tensor {
    var embedTensor = new Tensor(inputDom.high - inputDom.low + 1, config.dim);
    embedTensor.fill(0.0);
    const inputSize = inputDom.high - inputDom.low + 1;
    for i in inputDom {
      const localIdx = i - inputDom.low;
      const tokenIdx = (input[i]:int) % config.vocabSize;
      if tokenIdx >= 0 && tokenIdx < config.vocabSize {
        for j in 0..<config.dim {
          const embedIdx = tokenIdx * config.dim + j;
          const outIdx = localIdx * config.dim + j;
          if embedIdx < embeddings.dom.size && outIdx < embedTensor.dom.size then {
            embedTensor.data[outIdx] = embeddings.data[embedIdx];
          }
        }
      }
    }
    return embedTensor;
  }

  proc kanLayer(input: Tensor, layerIdx: int): Tensor {
    if layerIdx < 0 || layerIdx >= config.layers then {
      writeln("Invalid layer index");
      var emptyTensor = new Tensor(0, 0);
      return emptyTensor;
    }
    var output = new Tensor(input.s0, config.dim);
    output.fill(0.0);
    const layer = layers[layerIdx];
    const coeffs = layer.kanCoeffs;
    const biases = layer.kanBiases;
    const coeffsDom0Size = layer.kanCoeffsDom.dim(0);
    const coeffsDom1Size = layer.kanCoeffsDom.dim(1);
    for i in 0..<input.s0 {
      for j in 0..<config.dim {
        var sum = 0.0;
        for k in 0..<config.kanGrid {
          const inIdx = i * input.s1 + (k % input.s1);
          if inIdx < input.dom.size && k < coeffsDom0Size && j < coeffsDom1Size then {
            const inputVal = input.data[inIdx];
            const basisVal = cos(k:real * inputVal);
            sum += coeffs[k, j] * basisVal;
          }
        }
        sum += biases[j];
        const outIdx = i * config.dim + j;
        if outIdx < output.dom.size then output.data[outIdx] = sum;
      }
    }
    return output;
  }

  proc ssmStep(input: Tensor, layerIdx: int): Tensor {
    if layerIdx < 0 || layerIdx >= config.layers then {
      writeln("Invalid layer index");
      var emptyTensor = new Tensor(0, 0);
      return emptyTensor;
    }
    var output = new Tensor(input.s0, config.ssmDState);
    output.fill(0.0);
    const layer = layers[layerIdx];
    ref state = ssmStates[layerIdx];
    const limit = min(input.s1, 10);
    const limitReal = limit:real;
    for i in 0..<input.s0 {
      for j in 0..<config.ssmDState {
        const outIdx = i * config.ssmDState + j;
        const stateIdx = min(i, state.s0-1) * config.ssmDState + j;
        var inputSum = 0.0;
        for k in 0..<limit {
          const inIdx = i * input.s1 + k;
          if inIdx < input.dom.size then inputSum += input.data[inIdx];
        }
        inputSum /= limitReal;
        var stateVal = 0.0;
        if stateIdx < state.dom.size then stateVal = state.data[stateIdx];
        const val = layer.ssmA[j] * stateVal + layer.ssmB[j] * inputSum;
        if outIdx < output.dom.size then output.data[outIdx] = val;
        if stateIdx < state.dom.size then state.data[stateIdx] = val;
      }
    }
    return output;
  }

  proc tgnUpdate(input: Tensor, layerIdx: int): Tensor {
    if layerIdx < 0 || layerIdx >= config.layers then {
      writeln("Invalid layer index");
      var emptyTensor = new Tensor(0, 0);
      return emptyTensor;
    }
    var output = new Tensor(input.s0, config.tgnNodeFeat);
    output.fill(0.0);
    const layer = layers[layerIdx];
    const weights = layer.tgnWeights;
    const biases = layer.tgnBiases;
    const weightsDom0Size = layer.tgnWeightsDom.dim(0);
    const weightsDom1Size = layer.tgnWeightsDom.dim(1);
    for i in 0..<input.s0 {
      for j in 0..<config.tgnNodeFeat {
        var sum = 0.0;
        const limit = min(input.s1, config.tgnTimeDim);
        for k in 0..<limit {
          const inIdx = i * input.s1 + k;
          if inIdx < input.dom.size && j < weightsDom0Size && k < weightsDom1Size then {
            sum += input.data[inIdx] * weights[j, k];
          }
        }
        sum += biases[j];
        const outIdx = i * config.tgnNodeFeat + j;
        if outIdx < output.dom.size then output.data[outIdx] = sum;
      }
    }
    return output;
  }

  proc train(epochs: int) {
    for epoch in 0..<epochs {
      var inputDom = {0..<config.batchSize};
      var input: [inputDom] real;
      var rng = new randomStream(real, epoch);
      for i in inputDom do input[i] = ((rng.next() * config.vocabSize:real):int):real;
      var output = forward(inputDom, input);
      var loss = computeLoss(output);
      writeln("Epoch ", epoch, " Loss: ", loss);
    }
  }

  proc computeLoss(logits: Tensor): real {
    var sum = 0.0;
    for v in logits.data do sum += v * v;
    return sum / logits.dom.size:real;
  }
}

proc main() {
  var conf = new FMRNConfig();
  conf.layers = 4;
  conf.dim = 256;
  conf.batchSize = 8;
  conf.epochs = 10;
  conf.ssmDState = 16;
  conf.kanGrid = 5;
  conf.tgnNodeFeat = 64;
  conf.tgnTimeDim = 64;
  conf.vocabSize = 1000;
  var model = new owned FMRNModel(conf);
  var inputDom = {0..<conf.batchSize};
  var input: [inputDom] real;
  var rng = new randomStream(real, 123);
  for i in inputDom do input[i] = ((rng.next() * conf.vocabSize:real):int):real;
  var result = model.forward(inputDom, input);
  writeln("Model initialized and forward pass completed");
  writeln("Output shape: ", result.s0, " x ", result.s1);
  writeln("Sample output values:");
  for i in 0..<min(5, result.dom.size) do writeln("  ", result.data[i]);
  model.train(conf.epochs);
}

