    if velocityDom != params.dom {
      velocityDom = params.dom;
      forall (i, j) in velocityDom do velocity[i, j] = 0.0;
    }
    forall (i, j) in params.dom {
      velocity[i, j] = momentum * velocity[i, j] - lr * gradients.data[i, j];
      params.data[i, j] += velocity[i, j];
    }
  }
}

class FMRNModel {
  var config: FMRNConfig;

  var layersDom: domain(1);
  var layers: [layersDom] owned FMRNLayer?;

  var weights: Tensor;
  var embeddings: Tensor;

  var ssmStatesDom: domain(1);
  var ssmStates: [ssmStatesDom] Tensor;

  var tgnMemoryDom: domain(1);
  var tgnMemory: [tgnMemoryDom] Tensor;

  var quantum: owned QuantumSimulator?;
  var optimizer: owned CelestialZO?;

  proc init(conf: FMRNConfig) {
    this.config = conf;
    this.layersDom = {0..#conf.layers};
    this.ssmStatesDom = {0..#conf.layers};
    this.tgnMemoryDom = {0..#conf.ssmDState};
    this.weights = new Tensor(conf.dim, conf.vocabSize);
    this.embeddings = new Tensor(conf.vocabSize, conf.dim);
    this.complete();
  }

  proc postinit() {
    embeddings.fillRandom(42);
    weights.fillRandom(43);
    forall i in layersDom do
      layers[i] = new owned FMRNLayer(config.dim, config.ssmDState, config.kanGrid, config.tgnNodeFeat, config.tgnTimeDim, i);
    forall i in ssmStatesDom {
      ssmStates[i] = new Tensor(config.batchSize, config.ssmDState);
    }
    forall i in tgnMemoryDom {
      tgnMemory[i] = new Tensor(config.batchSize, config.tgnNodeFeat);
    }
    if config.quantumQubits > 0 then quantum = new owned QuantumSimulator();
    optimizer = new owned CelestialZO(config.lr);
  }

  proc forward(const ref input: [?D] int): Tensor {
    var embeds = embed(input);
    embeds.layerNorm();
    for l in 0..#config.layers {
      var residual = embeds.copy();
      var kanOut = kanLayer(embeds, l);
      kanOut.gelu();
      kanOut.layerNorm();
      var ssmOut = ssmStep(kanOut, l);
      ssmOut.gelu();
      ssmOut.layerNorm();
      var tgnOut = tgnUpdate(ssmOut, l);
      tgnOut.gelu();
      tgnOut.add(residual);
      tgnOut.layerNorm();
      embeds = tgnOut;
    }
    var logits = embeds.matmul(weights);
    return logits;
  }

  proc embed(const ref input: [?D] int): Tensor {
    const inputSize = D.size;
    var embedTensor = new Tensor(inputSize, config.dim);
    for idx in D {
      const i = idx - D.low;
      var tokenIdx = input[idx];
      if tokenIdx < 0 then tokenIdx = 0;
      tokenIdx = tokenIdx % config.vocabSize;
      for j in 0..#config.dim {
        embedTensor.data[i, j] = embeddings.data[tokenIdx, j];
      }
    }
    return embedTensor;
  }

  proc kanLayer(const ref input: Tensor, layerIdx: int): Tensor {
    if layerIdx < 0 || layerIdx >= config.layers {
      writeln("Invalid layer index: ", layerIdx);
      return new Tensor(0, 0);
    }
    var output = new Tensor(input.s0, config.dim);
    const layer = layers[layerIdx]!;
    forall i in 0..#input.s0 {
      for j in 0..#config.dim {
        var sum = 0.0;
        for k in 0..#config.kanGrid {
          const inVal = input.data[i, k % input.s1];
          const basisVal = cos(k:real * inVal);
          sum += layer.kanCoeffs[k, j] * basisVal;
        }
        sum += layer.kanBiases[j];
        output.data[i, j] = sum;
      }
    }
    return output;
  }

  proc ssmStep(const ref input: Tensor, layerIdx: int): Tensor {
    if layerIdx < 0 || layerIdx >= config.layers {
      writeln("Invalid layer index: ", layerIdx);
      return new Tensor(0, 0);
    }
    var output = new Tensor(input.s0, config.ssmDState);
    const layer = layers[layerIdx]!;
    ref state = ssmStates[layerIdx];
    forall i in 0..#input.s0 {
      for j in 0..#config.ssmDState {
        var inputSum = 0.0;
        const limit = if input.s1 < 10 then input.s1 else 10;
        for k in 0..#limit {
          inputSum += input.data[i, k];
        }
        inputSum /= limit:real;
        const stateVal = state.data[i, j];
        const val = layer.ssmA[j] * stateVal + layer.ssmB[j] * inputSum;
        output.data[i, j] = val;
        state.data[i, j] = val;
      }
    }
    return output;
  }

  proc tgnUpdate(const ref input: Tensor, layerIdx: int): Tensor {
    if layerIdx < 0 || layerIdx >= config.layers {
      writeln("Invalid layer index: ", layerIdx);
      return new Tensor(0, 0);
    }
    var output = new Tensor(input.s0, config.tgnNodeFeat);
    const layer = layers[layerIdx]!;
    forall i in 0..#input.s0 {
      for j in 0..#config.tgnNodeFeat {
        var sum = 0.0;
        const limit = if input.s1 < config.tgnTimeDim then input.s1 else config.tgnTimeDim;
        for k in 0..#limit {
          sum += input.data[i, k] * layer.tgnWeights[j, k];
        }
        sum += layer.tgnBiases[j];
        output.data[i, j] = sum;
      }
    }
    return output;
  }

  proc train(epochs: int) {
    for epoch in 0..#epochs {
      var inputDom = {0..#config.batchSize};
      var input: [inputDom] int;
      var rng = new randomStream(int, epoch, parSafe=true);
      for i in inputDom do input[i] = (rng.getNext() % config.vocabSize);
      var output = forward(input);
      var loss = computeLoss(output);
      writeln("Epoch ", epoch, " Loss: ", loss);
    }
  }

  proc computeLoss(const ref logits: Tensor): real {
    var sum: real = 0.0;
    forall (i, j) in logits.dom with (+ reduce sum) do sum += logits.data[i, j] * logits.data[i, j];
    const n = logits.numElements();
    return if n > 0 then sum / n:real else 0.0;
  }
}

proc main() {
  var conf = new FMRNConfig();
  var model = new owned FMRNModel(conf);
  var inputDom = {0..#conf.batchSize};
  var input: [inputDom] int;
  var rng = new randomStream(int, 123, parSafe=true);
  for i in inputDom do input[i] = (rng.getNext() % conf.vocabSize);
  var result = model.forward(input);
  writeln("Model initialized and forward pass completed");
  writeln("Output shape: ", result.s0, " x ", result.s1);
  writeln("Sample output values:");
  const sampleSize = if result.numElements() < 5 then result.numElements() else 5;
  for i in 0..#sampleSize {
     const row = i / result.s1;
     const col = i % result.s1;
     writeln("  ", result.data[row, col]);
  }
  model.train(conf.epochs);
}
